INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66269367', 66269367, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Alat Tulis Kantor Layanan Umum Intenal Kehumasan dan Pembinaan Kepegawaian', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 9000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Pengadaan Alat Tulis Kantor (ATK) untuk mendukung kelancaran layanan umum internal kehumasan dan pembinaan kepegawaian di lingkungan Biro Humas Kementerian Ketenagakerjaan, meliputi penyediaan barang habis pakai perkantoran yang digunakan dalam kegiatan administrasi persuratan, pengarsipan, dokumentasi, rapat/koordinasi, penyusunan bahan komunikasi, serta dukungan tata kelola kepegawaian. Pekerjaan mencakup penyediaan, pengemasan, pengiriman sampai lokasi yang ditentukan, serta serah terima barang sesuai kebutuhan operasional unit kerja selama periode pelaksanaan kegiatan.', 'ATK yang disediakan merupakan barang baru, asli, tidak cacat, dan layak pakai dengan kualitas minimal setara standar perkantoran, mencakup antara lain kertas (berbagai ukuran/gramatur sesuai kebutuhan), alat tulis (pulpen/pensil/spidol), perlengkapan pengarsipan (map/folder/ordner/label), perekat dan pengikat (lem/selotip/staples/clip/karet), perlengkapan meja dan administrasi (buku tulis/nota/agenda), serta kebutuhan penunjang rapat dan persuratan lainnya. Barang harus memiliki kesesuaian fungsi, ukuran, dan satuan, dikemas rapi, aman selama pengiriman, dan diterima dalam kondisi baik; jumlah/varian mengikuti daftar kebutuhan unit kerja, dengan mekanisme pemeriksaan kesesuaian jenis, kuantitas, dan mutu pada saat serah terima.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2640003);
