INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66268775', 66268775, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Konsultan Ahli Menteri Bidang Kemaritiman dan Sumber Daya Alam, Manajemen Proyek Sektor Publik, Manajemen SDM dan Reformasi Birokrasi Tahun Anggaran 2026.', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 211860000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Konsultan Ahli Menteri Bidang Kemaritiman dan Sumber Daya Alam, Manajemen Proyek Sektor Publik, Manajemen SDM dan Reformasi Birokrasi merupakan penugasan kepada individu yang akan bertanggungjawab untuk membantu dan mendukung kegiatan yang sesuai dengan bidang keahlian secara profesional untuk mendorong terbentuknya tata kelola pemerintahan yang baik, transparan, dan profesional dengan berorientasi pada arahan Menteri PPN/Kepala Bappenas sesuai Standar Kompetensi Nasional pada Tahun Anggaran 2026.', 'Secara umum lingkup kegiatan dari Konsultan Ahli Menteri Bidang Kemaritiman dan Sumber Daya Alam, Manajemen Proyek Sektor Publik, Manajemen SDM dan Reformasi Birokrasi adalah menganalisis, melaksanakan program-program, dan merancang kebijakan. Adapun hasil dari rencana strategis kerja akan menjadi rujukan dalam menyusun kerangka kerja sesuai bidang keahlian. Ruang lingkup kegiatan/pekerjaan Konsultan Ahli Menteri Bidang Kemaritiman dan Sumber Daya Alam, Manajemen Proyek Sektor Publik, Manajemen SDM dan Reformasi Birokrasi meliputi: Menyusun strategi komunikasi, diskusi, dan koordinasi dengan berbagai stakeholder terkait, sesuai dengan tata laksana yang berlaku di Bappenas. Mengkaji isu hambatan dan tantangan dalam Bidang Kemaritiman dan Sumber Daya Alam, Manajemen Proyek Sektor Publik, Manajemen SDM dan Reformasi Birokrasi. Memberikan rekomendasi dalam manajemen proyek sektor publik yang berdampak pada pemerataan dan pertumbuhan ekonomi. Mendukung pelaksanaan tugas administrasi dan substansi Sekretariat Kementerian PPN/Bappenas. Menyusun policy notes/policy brief terkait isu-isu seputar Bidang Kemaritiman dan Sumber Daya Alam, Manajemen Proyek Sektor Publik, Manajemen SDM dan Reformasi Birokrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2640245);
