INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267462', 66267462, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Konsumsi Rapat Biasa Monitoring dan Analisis Berita', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 37800000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '720 OK', 'Penyediaan konsumsi untuk rapat biasa dalam rangka pelaksanaan kegiatan Monitoring dan Analisis Berita di lingkungan Biro Humas Kementerian Ketenagakerjaan, meliputi penyediaan makanan dan/atau kudapan serta minuman bagi peserta rapat sesuai jumlah porsi yang ditetapkan berdasarkan daftar undangan/daftar hadir, termasuk persiapan, pengemasan, pengantaran, penataan, serta pengambilan kembali/penanganan sisa kemasan bila diperlukan. Penyedia wajib memastikan ketersediaan konsumsi pada waktu dan lokasi rapat yang ditentukan, serta mendukung kelancaran rapat melalui layanan yang tertib, responsif, dan sesuai ketentuan administrasi serta standar kebersihan yang berlaku.', 'Konsumsi yang disediakan harus layak konsumsi, higienis, aman, dan berkualitas baik dengan bahan yang masih segar, diolah pada hari yang sama, serta dikemas rapi dan tertutup (food grade) disertai identifikasi jenis menu; minuman disajikan dalam kemasan yang bersih dan aman. Pengiriman wajib tepat waktu sebelum rapat dimulai sesuai jadwal yang disepakati, jumlah porsi harus sesuai permintaan PPK/Pejabat yang ditunjuk, serta tersedia opsi menu alternatif untuk kebutuhan tertentu (misalnya non-pedas/vegetarian/halal) apabila diminta. Penyedia bertanggung jawab atas ketidaksesuaian jumlah, keterlambatan, atau penurunan mutu, dan wajib melakukan penggantian/penyempurnaan layanan sesuai arahan PPK berdasarkan hasil pemeriksaan/berita acara penerimaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2640696);
