INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267754', 66267754, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Konsumsi Rapat Biasa Fasilitasi dan Koordinasi Kerjasama dengan Lembaga Tinggi Negara, Pemerintah, dan Lembaga Non Pemerintah', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100800000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1920 OK', 'Penyedia menyediakan layanan konsumsi rapat biasa untuk mendukung pelaksanaan kegiatan fasilitasi dan koordinasi kerja sama Biro Humas Kementerian Ketenagakerjaan dengan lembaga tinggi negara, pemerintah, dan lembaga non-pemerintah, meliputi penyediaan makanan/minuman rapat sesuai jadwal dan jumlah peserta, pengantaran dan penataan konsumsi di lokasi rapat, serta memastikan ketersediaan konsumsi selama kegiatan berlangsung. Layanan dilaksanakan berdasarkan permintaan Biro Humas per jadwal rapat (hari/tanggal/jam), mencakup penyesuaian jenis konsumsi (misalnya snack/coffee break dan/atau makan) sesuai kebutuhan rapat, dengan tetap menjamin ketepatan waktu, kebersihan, dan kelayakan konsumsi, serta disertai administrasi serah terima sesuai mekanisme yang ditetapkan', 'Konsumsi rapat disediakan per porsi per peserta sesuai permintaan (snack/coffee break dan/atau makan siang/malam menyesuaikan waktu rapat) dengan menu layak, higienis, dan aman dikonsumsi; menggunakan bahan pangan yang baik, kemasan rapi dan tertutup, serta memperhatikan standar kebersihan proses produksi/penyajian dan ketentuan keamanan pangan; pengantaran dilakukan tepat waktu ke lokasi rapat yang ditentukan, porsi sesuai daftar hadir/konfirmasi jumlah peserta, dan disertai mekanisme kontrol kualitas (cek fisik, kelengkapan, dan kesesuaian) pada saat serah terima yang dibuktikan dengan berita acara/daftar penerimaan, serta menyediakan opsi penyesuaian menu sederhana (mis. nonpedas/vegetarian) apabila diminta sebelumnya oleh Biro Humas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2640818);
