INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66232193', 66232193, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA PELABUHAN KELAS III TELUK BATANG', 'Layanan Kebersihan Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Barat, Kayong Utara (Kab.)', 180648000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Layanan', '- Membersihkan seluruh area kerja, termasuk lantai, dinding, plafon, kaca, pintu, dan perabot, menjaga kebersihan toilet, pantry, ruang rapat, dan area publik. - Mengelola sampah harian: pengumpulan, pemisahan, dan pembuangan sesuai ketentuan. - Melakukan pembersihan khusus (deep cleaning) secara berkala sesuai jadwal. - Menyediakan dan mengisi ulang kebutuhan kebersihan (tissue, sabun, pengharum ruangan).', '1. Ruang Lingkup - Area yang dibersihkan: seluruh gedung kantor, ruang kerja, ruang rapat, toilet, pantry, koridor, tangga, lobby, dan area publik. - Termasuk pembersihan kaca, dinding, plafon, serta perabot kantor. - Pengelolaan sampah harian hingga ke tempat pembuangan akhir. 2. Standar Kualitas - Kebersihan lantai: bebas debu, noda, dan sampah setiap saat. - Toilet: bersih, tidak berbau, perlengkapan (tissue, sabun, pengharum) selalu tersedia. - Kaca/jendela: bebas noda, dibersihkan minimal sekali seminggu. - Pantry: meja, kursi, wastafel bersih, bebas sisa makanan. - Sampah: terangkut minimal 2 kali sehari, tidak menumpuk. 3. Frekuensi Pekerjaan - Pembersihan rutin: setiap hari kerja. - Toilet & pantry: minimal 3 kali sehari. - Pembersihan kaca: mingguan. - Deep cleaning: bulanan. 5. Tenaga Kerja - Jumlah tenaga kebersihan disesuaikan dengan luas area (misalnya 1 orang per 500 m²). - Tenaga kerja wajib menggunakan seragam, identitas, dan APD sesuai standar. - Memiliki pelatihan dasar kebersihan dan keselamatan kerja. 6. Pengawasan dan Pelaporan - Supervisor melakukan inspeksi harian. - Laporan kebersihan dibuat mingguan/bulanan. - Setiap kerusakan fasilitas segera dilaporkan ke pihak pengguna jasa.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2641109);
