INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66269764', 66269764, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Komputer Suplies Layanan Umum Internal Kehumasan dan Pembinaan Kepegawaian', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 12600000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Kegiatan penyediaan perlengkapan penunjang teknologi informasi dan administrasi perkantoran yang dibutuhkan untuk kelancaran operasional internal Biro Humas Kementerian Ketenagakerjaan, termasuk dukungan layanan dokumentasi/kehumasan, pengelolaan administrasi kepegawaian, serta kegiatan perkantoran sehari-hari yang terkait pemrosesan dokumen, komunikasi, dan arsip kerja; pengadaan mencakup penyediaan, pengiriman, dan penyerahan barang sesuai kebutuhan unit kerja agar ketersediaan suplies komputer terjaga, layanan tidak terhenti, dan pekerjaan rutin dapat berjalan efektif dan tepat waktu.', 'Barang yang disediakan berupa komputer suplies/perlengkapan penunjang TIK dan administrasi perkantoran yang kompatibel dengan perangkat yang sudah ada di lingkungan kerja (misalnya tinta/toner printer sesuai tipe perangkat, kertas cetak/fotokopi sesuai ukuran dan gramasi yang dibutuhkan, media penyimpanan seperti flashdisk/external storage sesuai kapasitas yang diperlukan, periferal sederhana seperti mouse/keyboard, kabel data/connector, dan/atau kebutuhan sejenis sesuai daftar kebutuhan unit kerja), dengan ketentuan barang baru, asli/bergaransi resmi (jika relevan), tidak kedaluwarsa/masa simpan aman (untuk tinta/toner), kualitas baik, kemasan utuh, serta disertai dokumen pendukung minimal nota/daftar barang dan bukti serah terima; pengiriman dilakukan ke lokasi yang ditetapkan PPK, penyerahan barang melalui pemeriksaan kesesuaian jenis, jumlah, dan kondisi sebelum dinyatakan diterima.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2641818);
