INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66269978', 66269978, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Tenaga Ahli Biro Humas', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pengadaan jasa konsultan Tenaga Ahli Biro Humas untuk memberikan dukungan profesional kepada Biro Humas Kementerian Ketenagakerjaan dalam perencanaan, pelaksanaan, dan evaluasi komunikasi publik, meliputi penyusunan strategi dan rencana komunikasi, pengelolaan isu dan krisis, penyusunan materi komunikasi (naskah siaran pers, talking points, Q&A, artikel, dan konten kanal digital), koordinasi dukungan kegiatan kehumasan, serta penyusunan laporan dan rekomendasi berbasis data (monitoring pemberitaan/percakapan publik) guna meningkatkan efektivitas diseminasi informasi, reputasi institusi, dan kualitas layanan informasi kepada masyarakat sesuai ketentuan yang berlaku.', 'Tenaga Ahli Biro Humas minimal berpendidikan S1 (diutamakan Ilmu Komunikasi/Jurnalistik/Humas atau bidang relevan) dengan pengalaman kerja kehumasan/komunikasi strategis paling sedikit 3 (tiga) tahun, memiliki kemampuan analisis isu, penulisan naskah kehumasan, perencanaan kampanye komunikasi, dan pengelolaan kanal digital; mampu menyusun output terukur berupa dokumen rencana komunikasi, paket materi komunikasi (siaran pers, rilis kegiatan, statement, Q&A, talking points), ringkasan monitoring media/percakapan publik, rekomendasi tindak lanjut, serta laporan berkala sesuai periode kontrak; bekerja dengan pola koordinasi harian/pekanan bersama PPK/Pejabat Teknis/Tim Humas, memenuhi ketepatan waktu, kualitas substansi, dan kerahasiaan informasi, serta seluruh hasil pekerjaan dapat diverifikasi melalui berita acara/lembar verifikasi dan dokumen deliverable yang disampaikan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2641831);
