INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66271248', 66271248, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Survey IKM', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Melaksanakan kegiatan Survei Indeks Kepuasan Masyarakat (IKM) untuk mengukur tingkat kepuasan pengguna layanan/produk komunikasi dan informasi publik Kementerian Ketenagakerjaan, mulai dari penyusunan rencana kerja dan instrumen survei, pengumpulan data responden secara terukur, pengolahan serta analisis hasil survei, hingga penyusunan laporan IKM yang memuat temuan, interpretasi, dan rekomendasi perbaikan layanan, termasuk paparan hasil kepada PPK/unit teknis serta serah terima seluruh keluaran pekerjaan sesuai ketentuan yang berlaku.', 'Penyedia wajib menyiapkan metodologi survei yang jelas dan dapat dipertanggungjawabkan (desain sampel/responden, teknik pengumpulan data, dan prosedur quality control), menyusun kuesioner IKM terstruktur beserta pedoman pengisian, melaksanakan survei (online/offline/telepon sesuai kebutuhan) dengan data responden yang tervalidasi dan terdokumentasi, melakukan pengolahan data (coding, cleaning, tabulasi) dan analisis (nilai IKM, sebaran per unsur/indikator, serta isu prioritas), serta menyerahkan output minimal berupa: instrumen final, dataset/rekapitulasi data, ringkasan eksekutif, laporan lengkap beserta rekomendasi rencana tindak lanjut, dan materi presentasi, dalam format digital yang dapat diedit dan siap arsip.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2643103);
