uaian jenis, jumlah, dan fungsi oleh PPK/Pejabat Penerima Hasil Pekerjaan sesuai kebutuhan operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2643843);
