INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66307937', 66307937, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Belanja Kegiatan Peningkatan Kompetensi Tenaga Pendidik', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kota)', 30060000, 'June 2026', 'APBN - RUPIAH MURNI (A), APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Paket pekerjaan ini merupakan pengadaan kebutuhan kegiatan dalam rangka peningkatan kompetensi tenaga pendidik di Politeknik Perkeretaapian Indonesia Madiun. Kegiatan meliputi pelaksanaan pemagangan dosen, sertifikasi insinyur, serta pemberian bantuan pendidikan bagi pegawai untuk program pendidikan lanjutan. Kegiatan ini bertujuan meningkatkan kapasitas, kompetensi, dan profesionalisme tenaga pendidik agar mampu mendukung penyelenggaraan pendidikan dan pelatihan di bidang perkeretaapian secara optimal.', 'Spesifikasi pekerjaan meliputi penyediaan kebutuhan kegiatan pemagangan dosen, pelaksanaan sertifikasi insinyur, serta pemberian bantuan pendidikan bagi pegawai yang mengikuti program pendidikan lanjutan. Pekerjaan mencakup penyediaan bahan kegiatan, dukungan perjalanan dinas, bantuan program sertifikasi, serta bantuan biaya pendidikan dan operasional selama masa studi sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2645532);
